package com.genealogy.source.repository;
import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.genealogy.common.persistence.*; import com.genealogy.source.entity.SourceAttachmentEntity; import com.genealogy.source.repository.mybatis.SourceAttachmentPersistenceMapper; import org.springframework.data.domain.*; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Repository @Transactional(readOnly=true) public class SourceAttachmentRepository { private final SourceAttachmentPersistenceMapper mapper; public SourceAttachmentRepository(SourceAttachmentPersistenceMapper mapper){this.mapper=mapper;} @Transactional public SourceAttachmentEntity save(SourceAttachmentEntity e){if(e.getId()==null)mapper.insert(e);else if(mapper.updateAllById(e)!=1)throw new IllegalStateException("Source attachment update expected one row for id "+e.getId());return e;} @Transactional public SourceAttachmentEntity saveAndFlush(SourceAttachmentEntity e){return save(e);} public Optional<SourceAttachmentEntity> findById(Long id){return Optional.ofNullable(id==null?null:mapper.selectById(id));} public List<SourceAttachmentEntity> findTop5BySourceIdAndDeletedAtIsNullOrderByCreatedAtDesc(Long id){return list(id,null,5);} public List<SourceAttachmentEntity> findTop10BySourceIdInAndDeletedAtIsNullOrderByCreatedAtDesc(Collection<Long> ids){if(ids==null||ids.isEmpty())return List.of();return mapper.selectList(Wrappers.<SourceAttachmentEntity>lambdaQuery().in(SourceAttachmentEntity::getSourceId,ids).isNull(SourceAttachmentEntity::getDeletedAt).orderByDesc(SourceAttachmentEntity::getCreatedAt).orderByDesc(SourceAttachmentEntity::getId).last("limit 10"));} public Page<SourceAttachmentEntity> findBySourceIdAndDeletedAtIsNullOrderByCreatedAtDesc(Long id,Pageable p){var q=Wrappers.<SourceAttachmentEntity>lambdaQuery().eq(SourceAttachmentEntity::getSourceId,id).isNull(SourceAttachmentEntity::getDeletedAt);long total=mapper.selectCount(q);if(total==0)return new PageImpl<>(List.of(),p,0);q.orderByDesc(SourceAttachmentEntity::getCreatedAt).orderByDesc(SourceAttachmentEntity::getId).last("limit "+p.getPageSize()+" offset "+p.getOffset());return new PageImpl<>(mapper.selectList(q),p,total);} public Optional<SourceAttachmentEntity> findByIdAndDeletedAtIsNull(Long id){return Optional.ofNullable(mapper.selectOne(Wrappers.<SourceAttachmentEntity>lambdaQuery().eq(SourceAttachmentEntity::getId,id).isNull(SourceAttachmentEntity::getDeletedAt)));} public int countBySourceIdAndDeletedAtIsNull(Long id){return Math.toIntExact(mapper.selectCount(Wrappers.<SourceAttachmentEntity>lambdaQuery().eq(SourceAttachmentEntity::getSourceId,id).isNull(SourceAttachmentEntity::getDeletedAt)));} public List<TargetCountProjection> countActiveByTargets(Long clanId,String type,Collection<Long> ids,String x){return ids==null||ids.isEmpty()?List.of():new ArrayList<>(mapper.countActiveByTargets(clanId,type,ids,x));} private List<SourceAttachmentEntity> list(Long id,String x,int n){return mapper.selectList(Wrappers.<SourceAttachmentEntity>lambdaQuery().eq(SourceAttachmentEntity::getSourceId,id).isNull(SourceAttachmentEntity::getDeletedAt).orderByDesc(SourceAttachmentEntity::getCreatedAt).orderByDesc(SourceAttachmentEntity::getId).last("limit "+n));} }
